[
  {
    "text": "A heading qualifies as 'titled or dedicated to the problem of translating long-term memory into embodied plans independently' if it explicitly contains the phrase 'long-term memory' and 'embodied plans' or a direct paraphrase such as 'converting episodic memories into motor actions' within the heading text.",
    "topic": "Explicit heading criteria"
  },
  {
    "text": "Examine the content under each section heading in the WorldLines paper for any standalone passage that formulates the general problem of translating long-term memory into embodied plans without coupling it to the paper's specific state reconstruction technique.",
    "topic": "Content-based dedicated treatment"
  },
  {
    "text": "Check whether the paper's description of memory-to-plan translation as converting episodic memories into plans necessarily entails the long-term nature of episodic memories and the potential embodiment of plans, and if so, whether the paper explicitly identifies this as an independent challenge.",
    "topic": "Implicit entailment and identification"
  },
  {
    "text": "Determine if the paper partitions the translation process into clearly delineated subproblems (retrieval, abstraction, grounding) and presents them as universal components required for using symbolic plans with any episodic memory system, independent of the reconstruction solution.",
    "topic": "Independent subproblem structure"
  }
]
